82	const BATCH_SIZE = 50;
83	const PROGRESS_FILE_PATH = resolveSovereignPath('memory/pedagogy/corpus/.progress');
84	
85	
86	interface ProgressState {
87	    items: { lastIndex: number; total: number };
88	    npcs: { lastIndex: number; total: number };
89	    quests: { lastIndex: number; total: number };
90	}
91	
92	// ──────────────────────────────────────────────────────
93	
94	function loadProgress(): ProgressState {
95	    if (existsSync(PROGRESS_FILE_PATH)) {
96	        try {
97	            return JSON.parse(readFileSync(PROGRESS_FILE_PATH, 'utf8'));
98	        } catch {
99	            logger.warn('Progress file corrupted, restarting from zero.');
100	        }
101	    }
102	    return {
103	        items: { lastIndex: 0, total: 0 },
104	        npcs: { lastIndex: 0, total: 0 },
105	        quests: { lastIndex: 0, total: 0 }
106	    };
107	}
108	
109	function saveProgress(state: ProgressState): void {
110	    writeFileSync(PROGRESS_FILE_PATH, JSON.stringify(state, null, 2), 'utf8');
111	}
112	
113	function formatVerifiedOutput(name: string, id: number, data: any): string {
114	    const tag = data?.tag || '[WIKI_ONLY]';
115	    let excerpt = 'No descriptive data available.';
116	
117	    if (data?.itemMeta?.examine) {
118	        excerpt = data.itemMeta.examine;
119	    } else if (data?.monsterMeta?.combatLevel) {
120	        excerpt = `Combat Level ${data.monsterMeta.combatLevel}`;
121	    } else if (data?.extract) {
122	        excerpt = data.extract.substring(0, 100) + '...';
123	    }
124	
125	    return `[${tag}] Entity ${id}: ${name}. ${excerpt}`;
126	}
127	
128	async function generate() {
129	    logger.info('Starting High-Fidelity Pedagogy Corpus Generation...');
130	
131	    const enricher = WikiEquipmentEnricher.getInstance();
132	    const corpusPath = resolveSovereignPath('memory/pedagogy/corpus/verified_entities.jsonl');
133	    const corpusDir = join(corpusPath, '..');
134	
135	    if (!existsSync(corpusDir)) {
136	        mkdirSync(corpusDir, { recursive: true });
137	    }
138	
139	    let progress = loadProgress();
140	
141	    // Note: Only clear file if we are starting from index 0 across all categories
142	    if (progress.items.lastIndex === 0 && progress.npcs.lastIndex === 0 && progress.quests.lastIndex === 0) {
143	        writeFileSync(corpusPath, '', 'utf8');
144	        logger.info('Fresh run: clearing previous corpus.');
145	    }
146	
147	    const appendToCorpus = (entries: any[]) => {
148	        if (entries.length === 0) return;
149	        const lines = entries.map(entry => JSON.stringify(entry)).join('\n');
150	        appendFileSync(corpusPath, lines + '\n', 'utf8');
151	    };
152	
153	    // ── 1. Item Corpus Generation (Two-Track) ─────────────────────────
154	    try {
155	        logger.info('Processing Item Catalog...');
156	        const rawItems = JSON.parse(readFileSync(CATALOG_PATHS.items, 'utf8'));
157	        progress.items.total = rawItems.length;
158	
159	        const itemsData = rawItems.map((item: any) => ({
160	            id: item.id,
161	            name: item.name,
162	            isPlaceholder: /^ITEMS?\s*\d+$/i.test(item.name) || !item.name,
163	        }));
164	
165	        for (let i = progress.items.lastIndex; i < itemsData.length; i += BATCH_SIZE) {
166	            const batch = itemsData.slice(i, i + BATCH_SIZE);
167	            const results = [];
168	
169	            for (const item of batch) {
170	                if (item.isPlaceholder) {
171	                    results.push({
172	                        instruction: `Describe cache entity ${item.id}`,
173	                        input: JSON.stringify({ id: item.id, source: 'cache_only' }),
174	                        output: `[CACHE_ONLY] Item ${item.id}. No wiki name available. Structural data only.`,
175	                        tags: ['[CACHE_ONLY]'],
176	                        verified: false,
177	                        cacheId: item.id
178	                    });
179	                } else {
180	                    const data = await enricher.enrichEntity(item.name);
181	                    results.push({
182	                        instruction: `Generate verified entity definition for ${item.name}`,
183	                        input: JSON.stringify({ id: item.id, wiki: data }),
184	                        output: formatVerifiedOutput(item.name, item.id, data),
185	                        tags: [data?.tag || '[WIKI_ONLY]'],
186	                        verified: data?.tag === '[VERIFIED]',
187	                        cacheId: item.id
188	                    });
189	                }
190	            }
191	            appendToCorpus(results);
192	            progress.items.lastIndex = i + batch.length;
193	            saveProgress(progress);
194	            logger.info({ processed: progress.items.lastIndex, total: progress.items.total }, 'Item batch complete');
195	        }
196	    } catch (err) {
197	        logger.error({ err }, 'Item corpus generation failed');
198	    }
199	
200	    // ── 2. Monster/NPC Corpus Generation (Two-Track) ──────────────────
201	    try {
202	        logger.info('Processing NPC Catalog...');
203	        const rawNpcs = JSON.parse(readFileSync(CATALOG_PATHS.npcs, 'utf8'));
204	        progress.npcs.total = rawNpcs.length;
205	
206	        const npcsData = rawNpcs.map((npc: any) => ({
207	            id: npc.id,
208	            name: npc.name,
209	            isPlaceholder: /^NPCS?\s*\d+$/i.test(npc.name) || !npc.name,
210	        }));
211	
212	        for (let i = progress.npcs.lastIndex; i < npcsData.length; i += BATCH_SIZE) {
213	            const batch = npcsData.slice(i, i + BATCH_SIZE);
214	            const results = [];
215	
216	            for (const npc of batch) {
217	                if (npc.isPlaceholder) {
218	                    results.push({
219	                        instruction: `Describe cache entity ${npc.id}`,
220	                        input: JSON.stringify({ id: npc.id, source: 'cache_only' }),
221	                        output: `[CACHE_ONLY] NPC ${npc.id}. No wiki name available. Structural data only.`,
222	                        tags: ['[CACHE_ONLY]'],
223	                        verified: false,
224	                        cacheId: npc.id
225	                    });
226	                } else {
227	                    const data = await enricher.enrichEntity(npc.name);
228	                    results.push({
229	                        instruction: `Generate verified entity definition for ${npc.name}`,
230	                        input: JSON.stringify({ id: npc.id, wiki: data }),
231	                        output: formatVerifiedOutput(npc.name, npc.id, data),
232	                        tags: [data?.tag || '[WIKI_ONLY]'],
233	                        verified: data?.tag === '[VERIFIED]',
234	                        cacheId: npc.id
235	                    });
236	                }
237	            }
238	            appendToCorpus(results);
239	            progress.npcs.lastIndex = i + batch.length;
240	            saveProgress(progress);
241	            logger.info({ processed: progress.npcs.lastIndex, total: progress.npcs.total }, 'NPC batch complete');
242	        }
243	    } catch (err) {
244	        logger.error({ err }, 'NPC corpus generation failed');
245	    }
246	
247	    // ── 3. Quest Corpus Generation ──────────────────────────────────
248	    try {
249	        logger.info('Processing Quest Manifest...');
250	        const questsData = JSON.parse(readFileSync(CATALOG_PATHS.quests, 'utf8'));
251	        progress.quests.total = questsData.length;
252	
253	        const results = [];
254	        for (let i = progress.quests.lastIndex; i < questsData.length; i++) {
255	            const quest = questsData[i];
256	            const data = await enricher.enrichGeneric(quest.title);
257	            if (data) {
258	                results.push({
259	                    instruction: `Generate verified entity definition for quest: ${quest.title}`,
260	                    input: JSON.stringify({ quest, wiki: data }),
261	                    output: `[WIKI_ONLY] Quest: ${quest.title}. ${data.extract ? data.extract.substring(0, 100) + '...' : 'No description available.'}`,
262	                    tags: ['[WIKI_ONLY]'],
263	                    verified: false
264	                });
265	            }
266	
267	            // Save every 10 quests to prevent loss
268	            if (i % 10 === 0) {
269	                appendToCorpus(results);
270	                results.length = 0;
271	                progress.quests.lastIndex = i + 1;
272	                saveProgress(progress);
273	            }
274	        }
275	        appendToCorpus(results);
276	        progress.quests.lastIndex = questsData.length;
277	        saveProgress(progress);
278	    } catch (err) {
279	        logger.error({ err }, 'Quest corpus generation failed');
280	    }
281	
282	    // ── 4. Mechanics Corpus Generation ─────────────────────────────────
283	    try {
284	        logger.info('Processing Mechanics Pages...');
285	        const results = [];
286	        for (const page of MECHANICS_PAGES) {
287	            const data = await enricher.enrichGeneric(page);
288	            if (data) {
289	                results.push({
290	                    instruction: `Explain the ${page} mechanic in RS3`,
291	                    input: JSON.stringify({ mechanic: page, wiki: data }),
292	                    output: formatVerifiedOutput(page, 0, data),
293	                    tags: ['[WIKI_ONLY]', '[MECHANIC]'],
294	                    verified: false
295	                });
296	            }
297	        }
298	        appendToCorpus(results);
299	        logger.info({ count: results.length }, 'Mechanics corpus generated successfully.');
300	    } catch (err) {
301	        logger.error({ err }, 'Mechanics corpus generation failed');
302	    }
303	}
304	
305	generate().catch(err => {
306	    logger.error({ err }, 'Corpus generation failed');
307	    process.exit(1);
308	});
