1	import * as fs from 'fs';
2	import * as path from 'path';
3	import { createLogger } from "../../utils/logger.js";
4	import { getSovereignRoot } from '../../utils/SovereignPathResolver.js';
5	import { Result, ok, err, VarbitSnapshot, CompositeCondition, GameState, SpatialSideEffect, SovereignAvatar } from '../../core/models.js';
6	import { PedagogyLimb } from './PedagogyLimb.js';
7	
8	const logger = createLogger('MechanicalSovereigntyLimb');
9	
10	export interface MechanicalLogicArtifact {
11	    region: string;
12	    metadata: any;
13	    sarcophagi?: any[];
14	    state_machines?: {
15	        [key: string]: any;
16	    };
17	    loot_chest?: any;
18	    rules?: any[]; // Array of general rules (e.g. for dynamic spatial effects)
19	}
20	
21	export class MechanicalSovereigntyLimb {
22	    private static instance: MechanicalSovereigntyLimb | undefined;
23	    private readonly logicDir: string;
24	    private loadedLogic: Map<string, MechanicalLogicArtifact> = new Map();
25	    private pedagogy?: PedagogyLimb;
26	
27	    public static getInstance(): MechanicalSovereigntyLimb {
28	        if (!this.instance) {
29	            this.instance = new MechanicalSovereigntyLimb();
30	        }
31	        return this.instance;
32	    }
33	
34	    public static resetInstance(): void {
35	        if (process.env.NODE_ENV === 'production') {
36	            throw new Error('resetInstance is forbidden in production');
37	        }
38	        this.instance = undefined;
39	    }
40	
41	    private constructor(pedagogy?: PedagogyLimb) {
42	        if (MechanicalSovereigntyLimb.instance) {
43	            throw new Error('Singleton violation: use MechanicalSovereigntyLimb.getInstance()');
44	        }
45	        this.logicDir = path.join(getSovereignRoot(), 'atlas', 'logic');
46	        this.pedagogy = pedagogy;
47	    }
48	    
49	    public injectPedagogy(pedagogy: PedagogyLimb) {
50	        this.pedagogy = pedagogy;
51	    }
52	
53	    /**
54	     * initialize - Prepares the mechanical substrate.
55	     */
56	    public async initialize(): Promise<Result<boolean>> {
57	        try {
58	            logger.info({ dir: this.logicDir }, 'Initializing MechanicalSovereigntyLimb...');
59	            
60	            if (!fs.existsSync(this.logicDir)) {
61	                fs.mkdirSync(this.logicDir, { recursive: true });
62	                logger.warn('Mechanical Atlas directory missing. Created blank substrate.');
63	            }
64	
65	            // Auto-load Barrows if synthesized
66	            await this.loadLogic('barrows');
67	            
68	            // Auto-load Global Logic for Dynamic Spatial Effects
69	            await this.loadLogic('follower');
70	            await this.loadLogic('object');
71	            
72	            logger.info(`MechanicalSovereigntyLimb active with ${this.loadedLogic.size} regions loaded.`);
73	            return ok(true);
74	        } catch (error) {
75	            logger.error({ error }, 'Failed to initialize MechanicalSovereigntyLimb.');
76	            return err(error as Error);
77	        }
78	    }
79	
80	    /**
81	     * loadLogic - Ingests a specific region's mechanical rules.
82	     */
83	    public async loadLogic(name: string): Promise<Result<void>> {
84	        let filename = name;
85	        if (!filename.endsWith('.json')) {
86	            filename = `${name}_logic.json`;
87	        }
88	
89	        const fullPath = path.join(this.logicDir, filename);
90	        if (!fs.existsSync(fullPath)) {
91	            return err(new Error(`Mechanical logic file not found: ${fullPath}`));
92	        }
93	
94	        try {
95	            const data = JSON.parse(fs.readFileSync(fullPath, 'utf8')) as MechanicalLogicArtifact;
96	            this.loadedLogic.set(data.region.toLowerCase(), data);
97	            logger.info({ region: data.region }, 'Ingested Mechanical Sovereignty Artifact.');
98	            return ok(undefined);
99	        } catch (error) {
100	            logger.error({ error, filename }, 'Failed to parse mechanical artifact.');
101	            return err(error as Error);
102	        }
103	    }
104	
105	    /**
106	     * getSpawningRule - Resolves the spawning logic for a specific object interaction.
107	     */
108	    public getSpawningRule(objectId: number, region: string = 'barrows'): Result<any> {
109	        const logic = this.loadedLogic.get(region.toLowerCase());
110	        if (!logic || !logic.sarcophagi) {
111	            return err(new Error(`No logic found for region: ${region}`));
112	        }
113	
114	        const sarcophagus = logic.sarcophagi.find(s => s.object_id === objectId);
115	        if (!sarcophagus) {
116	            return err(new Error(`No spawning rule for Object ID: ${objectId} in ${region}`));
117	        }
118	
119	        return ok(sarcophagus);
120	    }
121	
122	    /**
123	     * resolveStateTransition - Evaluates how a varbit change affects the mechanical world.
124	     */
125	    public resolveStateTransition(varbitId: number, value: number, region: string = 'barrows'): Result<any> {
126	        const logic = this.loadedLogic.get(region.toLowerCase());
127	        if (!logic || !logic.state_machines) {
128	            return err(new Error(`No state machines found for region: ${region}`));
129	        }
130	
131	        const killStates = logic.state_machines.brother_kill_states;
132	        const entry = killStates[varbitId.toString()];
133	        
134	        if (!entry) {
135	            return err(new Error(`No state transition mapped to Varbit: ${varbitId}`));
136	        }
137	
138	        return ok({
139	            varbit: varbitId,
140	            value,
141	            effect: entry.description || 'Unknown mechanical effect'
142	        });
143	    }
144	
145	    /**
146	     * evaluateLootLogic - Checks if the requirements for loot are met.
147	     */
148	    public evaluateLootLogic(chestId: number, region: string = 'barrows'): Result<any> {
149	        const logic = this.loadedLogic.get(region.toLowerCase());
150	        if (!logic || !logic.loot_chest || logic.loot_chest.object_id !== chestId) {
151	            return err(new Error(`No loot logic for Chest ID: ${chestId} in ${region}`));
152	        }
153	
154	        return ok(logic.loot_chest.unlock_condition);
155	    }
156	
157	    /**
158	     * getSpatialSideEffects - Evaluates if an entity has specific spatial side effects (e.g. blocking collision)
159	     * based on the current game state.
160	     */
161	    public async getSpatialSideEffects(
162	        entityId: number,
163	        context: GameState
164	    ): Promise<SpatialSideEffect | null> {
165	        for (const logic of this.loadedLogic.values()) {
166	            if (logic.rules) {
167	                const rule = logic.rules.find(r => r.entity_id === entityId);
168	                if (rule && rule.spatial_side_effects) {
169	                    const sideEffect = rule.spatial_side_effects as SpatialSideEffect;
170	                    
171	                    if (sideEffect.condition) {
172	                        const met = await this.evaluateStringCondition(sideEffect.condition, context);
173	                        if (!met) return null;
174	                    }
175	                    
176	                    return sideEffect;
177	                }
178	            }
179	        }
180	        return null;
181	    }
182	
183	    /**
184	     * evaluateCompositeCondition - Evaluates a set of conditions using AND/OR logic.
185	     */
186	    public async evaluateCompositeCondition(
187	        condition: CompositeCondition,
188	        context: GameState
189	    ): Promise<boolean> {
190	        if (condition.type === 'composite_and') {
191	            for (const cond of condition.conditions) {
192	                const met = await this.evaluateStringCondition(cond, context);
193	                if (!met) return false;
194	            }
195	            return true;
196	        }
197	        if (condition.type === 'composite_or') {
198	            for (const cond of condition.conditions) {
199	                const met = await this.evaluateStringCondition(cond, context);
200	                if (met) return true;
201	            }
202	            return false;
203	        }
204	        return false;
205	    }
206	
207	    /**
208	     * evaluateStringCondition - Parses and evaluates a string-based condition.
209	     * Supports varbits and basic functional checks.
210	     */
211	    public async evaluateStringCondition(
212	        condition: string,
213	        context: GameState
214	    ): Promise<boolean> {
215	        // Varbit matching: varbit_1234 == 1
216	        const varbitMatch = condition.match(/varbit_(\d+)\s*(==|!=|<|>|<=|>=)\s*(\d+)/);
217	        if (varbitMatch) {
218	            const [_, idStr, operator, valStr] = varbitMatch;
219	            const id = parseInt(idStr);
220	            const target = parseInt(valStr);
221	            const actual = context.varbits.get(id) || 0;
222	            switch (operator) {
223	                case '==': return actual === target;
224	                case '!=': return actual !== target;
225	                case '<': return actual < target;
226	                case '>': return actual > target;
227	                case '<=': return actual <= target;
228	                case '>=': return actual >= target;
229	            }
230	        }
231	
232	        // Inventory matching: has_item(12519) == true
233	        const itemMatch = condition.match(/has_item\((\d+)\)\s*==\s*(true|false)/);
234	        if (itemMatch) {
235	            const [_, idStr, stateStr] = itemMatch;
236	            const itemId = parseInt(idStr);
237	            const target = stateStr === 'true';
238	            
239	            // Query the primary avatar's 28-slot inventory
240	            const avatar = context.players.get('POG2_Sovereign');
241	            const has = avatar?.inventory.some(i => i?.id === itemId) || false;
242	            return has === target;
243	        }
244	
245	
246	        // Functional check matching: is_follower_active(player, 7015) == true
247	        if (condition.includes('is_follower_active')) {
248	            const match = condition.match(/is_follower_active\(.*,\s*(\d+)\)\s*==\s*true/);
249	            if (match) {
250	                const entityId = parseInt(match[1]);
251	                for (const npcs of context.npcSpatialIndex.values()) {
252	                    if (npcs.some(n => n.id === entityId)) return true;
253	                }
254	            }
255	            return false;
256	        }
257	
258	        // Level check: has_level("Attack", 90) == true
259	        const levelMatch = condition.match(/has_level\("(.*)",\s*(\d+)\)\s*==\s*(true|false)/);
260	        if (levelMatch) {
261	            const [_, skillName, levelStr, targetState] = levelMatch;
262	            const reqLevel = parseInt(levelStr);
263	            const target = targetState === 'true';
264	            
265	            const avatar = context.players.get('POG2_Sovereign');
266	            if (!avatar) return !target;
267	
268	            // Find skill by name
269	            const skill = Object.values(avatar.skills).find(s => s.name.toLowerCase() === skillName.toLowerCase());
270	            const has = (skill?.level || 0) >= reqLevel;
271	            return has === target;
272	        }
273	
274	        // Equipment Gating: can_equip(1289) == true
275	        const equipMatch = condition.match(/can_equip\((\d+)\)\s*==\s*(true|false)/);
276	        if (equipMatch) {
277	            const [_, idStr, stateStr] = equipMatch;
278	            const itemId = parseInt(idStr);
279	            const target = stateStr === 'true';
280	            
281	            const avatar = context.players.get('POG2_Sovereign');
282	            if (!avatar) return !target;
283	
284	            const res = this.canEquip(itemId, avatar);
285	            return res.ok === target;
286	        }
287	
288	        return false;
289	    }
